import{_ as t,o,c as s,ag as a}from"./chunks/framework.CxkNbRKf.js";const m=JSON.parse('{"title":"Customizing themes (header, footer, and styling)","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/configurations/customizing-themes.md","filePath":"installation-guide/configurations/customizing-themes.md","lastUpdated":1786379412000}'),n={name:"installation-guide/configurations/customizing-themes.md"};function r(d,e,c,i,l,g){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="customizing-themes-header-footer-and-styling" tabindex="-1">Customizing themes (header, footer, and styling) <a class="header-anchor" href="#customizing-themes-header-footer-and-styling" aria-label="Permalink to &quot;Customizing themes (header, footer, and styling)&quot;">​</a></h1><p>The <strong>public catalog</strong> appearance—top navigation, footer, typography, colors—is controlled by the <strong>site theme</strong>: PHP layouts and CSS under <code>themes/{theme-name}/</code>. The active theme is set in <strong><code>application/config/template.php</code></strong> via <strong><code>$template[&#39;theme_name&#39;]</code></strong> (by default <strong><code>nada52</code></strong>).</p><div class="tip custom-block"><p class="custom-block-title">Administrator settings vs theme files</p><p><strong>Website title</strong> and <strong>Website footer</strong> can be edited under <a href="/nada-documentation/admin-guide/web-ui/site-configurations.html">Site configurations</a>. The theme must <strong>output</strong> those values where you want them (for example <code>website_title</code> is commonly used in the header/footer). If your footer does not show the admin <strong>Website footer</strong> text, edit the theme’s <strong><code>footer.php</code></strong> to include <code>&lt;?php echo $this-&gt;config-&gt;item(&#39;website_footer&#39;); ?&gt;</code> where appropriate.</p></div><h2 id="when-to-customize-nada52-directly" tabindex="-1">When to customize <code>nada52</code> directly <a class="header-anchor" href="#when-to-customize-nada52-directly" aria-label="Permalink to &quot;When to customize `nada52` directly&quot;">​</a></h2><p>For <strong>minor styling</strong> or <strong>only</strong> changing the <strong>header</strong> and <strong>footer</strong>, you can edit the <strong>default <code>nada52</code> theme</strong> in place:</p><ul><li><strong><code>themes/nada52/header.php</code></strong> — navbar, logo area, site title block.</li><li><strong><code>themes/nada52/footer.php</code></strong> — footer columns, copyright line, links.</li><li>Related includes such as <strong><code>nav-menu.php</code></strong>, <strong><code>lang-bar.php</code></strong>, <strong><code>footer_top.php</code></strong> if your layout uses them (see <strong><code>layout.php</code></strong>).</li></ul><p>Keep backups or use version control: upgrading NADA may overwrite files under <strong><code>themes/nada52/</code></strong> unless you exclude them deliberately.</p><h2 id="custom-css-custom-css" tabindex="-1">Custom CSS (<code>custom.css</code>) <a class="header-anchor" href="#custom-css-custom-css" aria-label="Permalink to &quot;Custom CSS (`custom.css`)&quot;">​</a></h2><p>Small visual tweaks (fonts, spacing, colors) should go in:</p><p><strong><code>themes/nada52/css/custom.css</code></strong></p><p>That file is linked from <strong><code>themes/nada52/head.php</code></strong>, so rules you add there apply across the themed pages without editing core stylesheets such as <strong><code>style.css</code></strong>.</p><p>Prefer <strong><code>custom.css</code></strong> for overrides so stock <strong><code>css/style.css</code></strong> stays easier to compare on upgrades.</p><h2 id="larger-or-risky-changes-copy-the-theme" tabindex="-1">Larger or risky changes: copy the theme <a class="header-anchor" href="#larger-or-risky-changes-copy-the-theme" aria-label="Permalink to &quot;Larger or risky changes: copy the theme&quot;">​</a></h2><p>If you plan <strong>heavy</strong> layout changes or want clean merges when upgrading:</p><ol><li>Copy <strong><code>themes/nada52</code></strong> to a new folder, e.g. <strong><code>themes/my_catalog</code></strong>.</li><li>Set <strong><code>$template[&#39;theme_name&#39;]</code></strong> in <strong><code>application/config/template.php</code></strong> to <strong><code>my_catalog</code></strong> (folder name).</li><li>Edit <strong><code>header.php</code></strong>, <strong><code>footer.php</code></strong>, <strong><code>layout.php</code></strong>, and <strong><code>css/custom.css</code></strong> inside <strong><code>themes/my_catalog/</code></strong>.</li></ol><h2 id="main-files-to-know" tabindex="-1">Main files to know <a class="header-anchor" href="#main-files-to-know" aria-label="Permalink to &quot;Main files to know&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Typical files (<code>nada52</code>)</th></tr></thead><tbody><tr><td>Page shell</td><td><code>layout.php</code> — wraps <code>&lt;head&gt;</code>, header, content area, footer</td></tr><tr><td>Assets / <code>&lt;head&gt;</code></td><td><code>head.php</code> — loads CSS including <strong><code>css/custom.css</code></strong></td></tr><tr><td>Header</td><td><code>header.php</code></td></tr><tr><td>Footer</td><td><code>footer.php</code>, optional <code>footer_top.php</code></td></tr><tr><td>Styles</td><td><code>css/style.css</code>, <strong><code>css/custom.css</code></strong> (your overrides)</td></tr><tr><td>Images</td><td><code>images/</code> — logos and icons referenced from header/footer</td></tr></tbody></table><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/nada-documentation/admin-guide/web-ui/customizing-home-page.html">Customizing the home page</a> — body content at <code>/</code>, static views under <code>application/views/static/custom/</code>.</li><li><a href="/nada-documentation/installation-guide/configurations/google-analytics.html">Tracking website traffic using Google Analytics</a> — injecting scripts (often in <code>layout.php</code> / <code>&lt;head&gt;</code>).</li><li><a href="/nada-documentation/admin-guide/web-ui/site-configurations.html">Site configurations</a> — <strong>Website title</strong>, <strong>Website footer</strong>, caching.</li></ul>',19)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
